css:
/* Web Page container */
#client-appointment-page {
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
}

#client-appointment-page *,
#client-appointment-page *::before,
#client-appointment-page *::after {
  box-sizing: border-box;
}

/* Prevent Frappe website/theme rules from breaking form controls */
#client-appointment-page input,
#client-appointment-page select,
#client-appointment-page button {
  font-family: inherit;
}

/* ── Base ── */
.pa-board {
  font-family: Arial, sans-serif;
  background: #f0f4f8;
  padding: 16px;
  border-radius: 14px;
  color: #1f2937;
}

/* ── Header ── */
.pa-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-end;
  background: #fff;
  padding: 16px 20px;
  border-radius: 14px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.07);
  margin-bottom: 14px;
  border: 1px solid #e5e7eb;
}

.pa-header h2 {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  color: #111827;
}

.pa-header p {
  margin: 3px 0 0;
  font-size: 13px;
  color: #6b7280;
}

/* ── Filters ── */
.pa-filters {
  display: flex;
  gap: 10px;
  align-items: flex-end;
  flex-wrap: wrap;
}

.pa-filters div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.pa-filters label {
  font-size: 11px;
  font-weight: 600;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.pa-filters select,
.pa-filters input[type="date"] {
  height: 36px;
  min-width: 160px;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  padding: 0 10px;
  font-size: 13px;
  background: #fff;
  color: #111827;
  transition: border-color 0.15s;
}

.pa-filters select:focus,
.pa-filters input[type="date"]:focus {
  outline: none;
  border-color: #15803d;
  box-shadow: 0 0 0 3px rgba(21,128,61,0.12);
}

.refresh-btn {
  height: 36px;
  border: none;
  border-radius: 8px;
  background: #15803d;
  color: #fff;
  padding: 0 18px;
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.refresh-btn:hover  { background: #166534; }
.refresh-btn:active { transform: scale(0.97); }

/* ── Summary Cards ── */
.pa-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(130px, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.summary-card {
  background: #fff;
  border-radius: 12px;
  padding: 14px 16px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
  border: 1px solid #e5e7eb;
  border-top: 3px solid #16a34a;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.summary-card:nth-child(2) { border-top-color: #2563eb; }
.summary-card:nth-child(3) { border-top-color: #7c3aed; }
.summary-card:nth-child(4) { border-top-color: #dc2626; }

.summary-card span {
  font-size: 11px;
  font-weight: 600;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.summary-card strong {
  font-size: 26px;
  font-weight: 700;
  color: #111827;
  line-height: 1.1;
}

/* ── Table Wrapper ── */
.pa-table-wrap {
  background: #fff;
  border-radius: 14px;
  padding: 0;
  overflow: auto;
  max-height: 640px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.07);
  border: 1px solid #e5e7eb;
}

/* ── Table ── */
.pa-table {
  width: 100%;
  min-width: 900px;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 13px;
}

.pa-table thead {
  position: sticky;
  top: 0;
  z-index: 3;
}

.pa-table thead th {
  background: #f8fafc;
  padding: 10px 10px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #374151;
  border-bottom: 2px solid #e5e7eb;
  text-align: left;
  white-space: nowrap;
}
.navbar{display:none;}
.web-footer{display:none}
.pa-table thead th:first-child {
  position: sticky;
  left: 0;
  z-index: 4;
  background: #f0fdf4;
  color: #166534;
  width: 1%;
  min-width: 0;
  white-space: nowrap;
  text-align: center;
  padding: 8px 10px;
  font-size: 18px;
}

.pa-table tbody tr:hover td {
  background: #fafafa;
}

.pa-table td {
  padding: 4px 6px;
  min-width: 130px;
  height: 50px;
  border-bottom: 1px solid #f1f5f9;
  vertical-align: middle;
}

.pa-table td.time-cell {
  min-width: 0;
}

.time-cell {
  position: sticky;
  left: 0;
  z-index: 2;
  background: #f0fdf4;
  font-size: 12px;
  font-weight: 500;
  color: #166534;
  width: 1%;
  min-width: 0;
  white-space: nowrap;
  border-right: 0.5px solid #dcfce7;
  text-align: center;
  padding: 0 10px;
}

/* ── Empty Slots ── */
.empty-slot {
  background: #fafafa;
  text-align: center;
  vertical-align: middle !important;
  transition: background 0.15s;
}

.empty-slot:hover {
  background: #f0fdf4;
}

.add-appt-btn {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 1.5px dashed #86efac;
  background: transparent;
  color: #16a34a;
  padding: 0;
  font-size: 18px;
  line-height: 1;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}

.add-appt-btn:hover {
  background: #dcfce7;
  border-color: #16a34a;
  border-style: solid;
}

.add-appt-btn:active {
  transform: scale(0.93);
}

/* ── Appointment Cell ── */
.appt-cell {
  padding: 6px 8px;
  border-radius: 6px;
  background: #eff6ff;
  border-left: 3px solid transparent;
  cursor: pointer;
  transition: box-shadow 0.15s, opacity 0.15s;
}

.appt-cell:hover {
  box-shadow: 0 2px 8px rgba(59,130,246,0.18);
  opacity: 0.92;
}

.appt-patient {
  font-size: 12px;
  font-weight: 500;
  color: #1e3a5f;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 120px;
  margin-bottom: 0;
}

.appt-status {
  display: inline-block;
  font-size: 10px;
  padding: 2px 7px;
  border-radius: 999px;
  background: #dbeafe;
  color: #1d4ed8;
  font-weight: 600;
  margin-bottom: 2px;
}

.appt-id {
  font-size: 10px;
  color: #3b82f6;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 120px;
  margin-top: 2px;
}

/* ── Status variants ── */
.status-cancel {
  background: #fff1f2;
  border-left-color: #ef4444;
}
.status-cancel .appt-patient { color: #7f1d1d; }
.status-cancel .appt-id      { color: #ef4444; }


.status-closed {
  background: #f0fdf4;
  border-left-color: #16a34a;
}
.status-closed .appt-patient { color: #14532d; }
.status-closed .appt-id      { color: #16a34a; }

/* ── No Data ── */
.no-data {
  padding: 40px;
  text-align: center;
  color: #9ca3af;
  font-size: 14px;
}

/* ══════════════════════════════════════
   MODAL
══════════════════════════════════════ */
.pa-modal {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 16px;
  backdrop-filter: blur(2px);
}

.pa-modal.hidden { display: none; }

.pa-modal-box {
  width: 100%;
  max-width: 780px;
  max-height: 90vh;
  background: #fff;
  border-radius: 18px;
  overflow: hidden;
  border: none !important;
  outline: none !important;
  box-shadow: 0 24px 60px rgba(0,0,0,0.22);
  display: flex;
  flex-direction: column;
  animation: modalIn 0.18s ease;
}

@keyframes modalIn {
  from { opacity: 0; transform: translateY(12px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

.modal-head {
  background: #15803d;
  color: #fff;
  padding: 15px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}

.modal-head h3 {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.modal-close {
  border: none;
  background: rgba(255,255,255,0.15);
  color: #fff;
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}

.modal-close:hover { background: rgba(255,255,255,0.28); }

.modal-body {
  padding: 20px;
  overflow-y: auto;
  flex: 1;
  background: #fff;
  border: none;
  outline: none;
}

/* ── Form Grid ── */
.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px 20px;
}

.form-row {
  display: flex;
  flex-direction: column;
  gap: 5px;
  position: relative;
}

.form-row label {
  font-size: 12px;
  font-weight: 700;
  color: #374151;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.form-row label span { color: #dc2626; }

.form-row input,
.form-row select {
  height: 40px;
  border: 1.5px solid #e5e7eb;
  border-radius: 9px;
  padding: 0 12px;
  font-size: 14px;
  color: #111827;
  background: #f9fafb;
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}

.form-row input:not([readonly]):focus,
.form-row select:focus {
  outline: none;
  border-color: #15803d;
  background: #fff;
  box-shadow: 0 0 0 3px rgba(21,128,61,0.12);
}

.form-row input[readonly] {
  background: #f3f4f6;
  color: #6b7280;
  cursor: default;
}

/* ── Suggestions ── */
.client-suggestions,
.service-room-suggestions,
.category-suggestions,
.concern-suggestions {
  position: absolute;
  top: calc(100% + 2px);
  left: 0;
  right: 0;
  background: #fff;
  border: 1.5px solid #d1d5db;
  border-radius: 10px;
  max-height: 220px;
  overflow-y: auto;
  box-shadow: 0 8px 24px rgba(0,0,0,0.13);
  z-index: 10001;
}

.client-suggestions.hidden,
.service-room-suggestions.hidden,
.category-suggestions.hidden,
.concern-suggestions.hidden {
  display: none;
}

.client-option {
  padding: 9px 12px;
  cursor: pointer;
  border-bottom: 1px solid #f1f5f9;
  font-size: 13px;
  transition: background 0.1s;
}

.client-option:last-child { border-bottom: none; }
.client-option:hover      { background: #f0fdf4; }

.client-option strong {
  display: block;
  color: #111827;
  font-size: 13px;
}

.client-option span {
  display: block;
  margin-top: 1px;
  font-size: 11px;
  color: #9ca3af;
}

/* ── Section title ── */
.section-title {
  font-size: 13px;
  font-weight: 700;
  color: #374151;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-top: 1px solid #e5e7eb;
  padding-top: 16px;
  margin: 20px 0 10px;
}

/* ── Modal Actions ── */
.modal-actions {
  padding: 14px 20px;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  background: #f9fafb;
  border-top: 1px solid #e5e7eb;
  flex-shrink: 0;
}

.cancel-btn,
.create-btn {
  border: none;
  border-radius: 9px;
  height: 40px;
  padding: 0 20px;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.cancel-btn {
  background: #f3f4f6;
  color: #374151;
  border: 1.5px solid #e5e7eb;
}

.cancel-btn:hover  { background: #e5e7eb; }
.cancel-btn:active { transform: scale(0.97); }

.create-btn {
  background: #15803d;
  color: #fff;
}

.create-btn:hover   { background: #166534; }
.create-btn:active  { transform: scale(0.97); }
.create-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
}

/* ── Slot Preview ── */
.slot-preview-box {
  margin-top: 18px;
  border-top: 1px solid #e5e7eb;
  padding-top: 18px;
  text-align: center;
}

.slot-preview-box.hidden { display: none; }

.slot-title {
  font-size: 14px;
  color: #374151;
  margin-bottom: 14px;
  line-height: 1.8;
}

.slot-list {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px 14px;
}

.slot-btn {
  border: 1.5px solid #e5e7eb;
  background: #f9fafb;
  color: #374151;
  border-radius: 9px;
  padding: 8px 14px;
  font-size: 14px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}

.slot-btn:hover {
  background: #f0fdf4;
  border-color: #86efac;
  color: #15803d;
}

.slot-btn.disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.slot-btn.selected {
  background: #166534;
  color: #fff;
  border-color: #166534;
  font-weight: 700;
  box-shadow: 0 0 0 3px rgba(22,101,52,0.15);
}

/* ── Responsive ── */
@media (max-width: 768px) {
  .pa-header {
    flex-direction: column;
    align-items: stretch;
  }

  .pa-summary {
    grid-template-columns: repeat(2, 1fr);
  }

  .pa-filters select,
  .pa-filters input { min-width: 100%; }

  .form-grid { grid-template-columns: 1fr; }
}

.pa-modal > * {
  outline: none !important;
  border: none !important;
}

.pa-modal-box .modal-body .form-grid {
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}

/* Scheduled — blue */
.status-scheduled {
  background: #eff6ff;
  border-left-color: #2563eb;
}
.status-scheduled .appt-patient { color: #1e3a5f; }
.status-scheduled .appt-id      { color: #2563eb; }

/* Closed — green */
.status-closed {
  background: #f0fdf4;
  border-left-color: #16a34a;
}
.status-closed .appt-patient { color: #14532d; }
.status-closed .appt-id      { color: #16a34a; }

/* Cancel — red */
.status-cancel {
  background: #fff1f2;
  border-left-color: #dc2626;
}
.status-cancel .appt-patient { color: #7f1d1d; }
.status-cancel .appt-id      { color: #dc2626; }

/* Re-Scheduled — amber */
.status-rescheduled {
  background: #fffbeb;
  border-left-color: #d97706;
}
.status-rescheduled .appt-patient { color: #78350f; }
.status-rescheduled .appt-id      { color: #d97706; }

/* Re-Confirm — violet */
.status-reconfirm {
  background: #f5f3ff;
  border-left-color: #7c3aed;
}
.status-reconfirm .appt-patient { color: #3b0764; }
.status-reconfirm .appt-id      { color: #7c3aed; }

/* Not Answering — slate with stronger contrast */
.status-notanswering {
  background: #f1f5f9;
  border-left-color: #475569;
}
.status-notanswering .appt-patient { color: #1e293b; }
.status-notanswering .appt-id      { color: #475569; }

.appt-detail-modal {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10000;
  padding: 16px;
  backdrop-filter: blur(2px);
}

.appt-detail-modal.hidden {
  display: none;
}

.appt-detail-box {
  width: 100%;
  max-width: 720px;
  max-height: 90vh;
  background: #fff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 24px 60px rgba(0,0,0,0.22);
  display: flex;
  flex-direction: column;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.detail-item {
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  padding: 10px 12px;
}

.detail-item span {
  display: block;
  font-size: 11px;
  font-weight: 700;
  color: #6b7280;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.detail-item strong {
  font-size: 14px;
  color: #111827;
  font-weight: 600;
}

.detail-status-row {
  margin-top: 18px;
}

.detail-loading,
.detail-error {
  padding: 24px;
  text-align: center;
  color: #6b7280;
}

.detail-error {
  color: #dc2626;
}

.detail-save-btn {
  background: #15803d;
  color: #fff;
  border: none;
  border-radius: 9px;
  height: 40px;
  padding: 0 20px;
  font-weight: 700;
  cursor: pointer;
}

.detail-save-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.detail-cancel-btn {
  background: #f3f4f6;
  color: #374151;
  border: 1.5px solid #e5e7eb;
  border-radius: 9px;
  height: 40px;
  padding: 0 20px;
  font-weight: 700;
  cursor: pointer;
}

@media (max-width: 768px) {
  .detail-grid {
    grid-template-columns: 1fr;
  }
}

.detail-status-inline select {
  width: 100%;
  height: 38px;
  border: 1.5px solid #d1d5db;
  border-radius: 9px;
  padding: 0 10px;
  font-size: 13px;
  font-weight: 700;
  color: #111827;
  background: #fff;
}

.reschedule-box {
  margin-top: 16px;
  padding: 14px;
  background: #f8fafc;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
}

.reschedule-box.hidden {
  display: none;
}

.reschedule-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.detail-modal-close {
  border: none;
  background: rgba(255,255,255,0.18);
  color: #fff;
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.detail-modal-close:hover {
  background: rgba(255,255,255,0.32);
}

.slot-past{
  background:#f8fafc;
  color:#9ca3af;
  text-align:center;
  font-weight:600;
}

/* Modal Inputs Compact */
.pa-modal .form-row {
  margin-bottom: 10px;
}

.pa-modal label {
  font-size: 12px;
  margin-bottom: 4px;
  display: block;
}

.pa-modal input,
.pa-modal select {
  height: 34px;          /* reduce from typical 42-44 */
  min-height: 34px;
  padding: 5px 10px;
  font-size: 13px;
  border-radius: 6px;
  line-height: 1.2;
}

/* Search fields */
.modal-client,
.modal-service-room,
.modal-category,
.modal-concern {
  height: 34px;
  padding: 5px 10px;
}

/* Readonly fields */
.modal-client-details,
.modal-date-time-label {
  height: 34px;
  padding: 5px 10px;
  background: #f8f9fa;
}

/* Dropdown suggestions tighter */
.client-option {
  padding: 7px 10px;
  font-size: 13px;
}

.client-option span {
  font-size: 11px;
}

/* Reduce grid spacing */
.form-grid {
  gap: 18px;
}

/* Buttons slightly shorter */
.modal-actions button {
  height: 34px;
  padding: 0 14px;
  font-size: 13px;
}

javascript:
(function () {
  function initClientAppointmentScheduler() {
    var root = document.querySelector("#client-appointment-page");

    if (!root) {
      void 0;
      return;
    }

  var branchFilter       = root.querySelector(".branch-filter");
  var dateFilter         = root.querySelector(".date-filter");
  var refreshBtn         = root.querySelector(".refresh-btn");
  var tableHead          = root.querySelector(".pa-table-head");
  var tableBody          = root.querySelector(".pa-table-body");
  var totalCount         = root.querySelector(".total-count");
  var availableCount     = root.querySelector(".available-count");
  var roomCount          = root.querySelector(".room-count");
  var cancelCount        = root.querySelector(".cancel-count");
  var modal              = root.querySelector(".pa-modal");
  var modalClose         = root.querySelector(".modal-close");
  var cancelBtn          = root.querySelector(".cancel-btn");
  var createBtn          = root.querySelector(".create-btn");
  var modalClient        = root.querySelector(".modal-client");
