  function xhrPost(method, args, onSuccess, onError) {
    var xhr = new XMLHttpRequest();
    xhr.open("POST", "/api/method/" + method, true);
    xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
    xhr.setRequestHeader("X-Frappe-CSRF-Token", frappe.csrf_token);

    xhr.onreadystatechange = function () {
      if (xhr.readyState !== 4) return;

      if (xhr.status === 200) {
        try {
          var data = JSON.parse(xhr.responseText);
          onSuccess(data);
        } catch(e) {
          onError("JSON parse error: " + e.message);
        }
      } else {
        onError("HTTP " + xhr.status + ": " + xhr.responseText);
      }
    };

    var body = Object.keys(args).map(function(k) {
      return encodeURIComponent(k) + "=" + encodeURIComponent(
        typeof args[k] === "object" ? JSON.stringify(args[k]) : args[k]
      );
    }).join("&");

    xhr.send(body);
  }

  function xhrGet(url, onSuccess, onError) {
    var xhr = new XMLHttpRequest();
    xhr.open("GET", url, true);

    xhr.onreadystatechange = function () {
      if (xhr.readyState !== 4) return;

      if (xhr.status === 200) {
        try {
          onSuccess(JSON.parse(xhr.responseText));
        } catch (e) {
          onError("JSON parse error: " + e.message);
        }
      } else {
        onError("HTTP " + xhr.status + ": " + xhr.responseText);
      }
    };

    xhr.send();
  }

