      }, 220);
    }

    input.addEventListener("focus", runSearch);
    input.addEventListener("input", runSearch);
    input.addEventListener("blur", function () {
      setTimeout(function () {
        if (!suggestionsBox.matches(":hover")) {
          suggestionsBox.classList.add("hidden");
