    function loadClientTherapyPlans(patientName) {
    clientTherapyTypes = [];
    selectedConcern = "";
    selectedCategory = "";

    if (modalConcern) {
      modalConcern.value = "";
      modalConcern.placeholder = "Loading pending concerns...";
    }

    if (modalCategory) {
      modalCategory.value = "";
    }

    /*
      IMPORTANT:
      Do not query therapy_type or service_unit here.
      Frappe reportview is rejecting tabTherapy Plan.therapy_type.
      So we fetch only safe direct fields first.
    */
    xhrPost("frappe.desk.reportview.get", {
      doctype: "Therapy Plan",
      fields: JSON.stringify([
        "`tabTherapy Plan`.`name`",
        "`tabTherapy Plan`.`patient`",
        "`tabTherapy Plan`.`start_date`",
        "`tabTherapy Plan`.`modified`"
      ]),
      filters: JSON.stringify([
        ["Therapy Plan", "patient", "=", patientName]
      ]),
      order_by: "`tabTherapy Plan`.`modified` desc",
      start: 0,
      page_length: 100,
      view: "List",
      group_by: "",
      with_comment_count: 1
    }, function (data) {
      var rows = data.message && data.message.values ? data.message.values : [];

      void 0;
      void 0;

      if (!rows.length) {
        modalConcern.placeholder = "No therapy plans found";
        concernSuggestions.innerHTML =
          '<div class="client-option">No therapy plans found for: ' +
          escapeHtml(patientName) +
          '</div>';
        concernSuggestions.classList.remove("hidden");
        toggleCreateButton();
        return;
      }

      var pendingList = [];
      var loadedCount = 0;

      rows.forEach(function (r) {
        var planName = r[0];
        var planStartDate = r[2] || "";

        xhrGet(
          "/api/method/frappe.desk.form.load.getdoc?doctype=Therapy%20Plan&name=" +
            encodeURIComponent(planName) +
            "&_=" + Date.now(),

          function (res) {
            loadedCount++;

            var doc = res.docs && res.docs[0] ? res.docs[0] : null;

            if (doc) {
              var planCategory =
                doc.service_unit ||
                doc.category ||
                "";

              var details =
                doc.therapy_plan_details ||
                doc.therapy_plan_detail ||
                doc.therapy_plan_table ||
                doc.therapy_details ||
                doc.plan_details ||
                [];

              /*
                If exact child table fieldname is unknown,
                scan all child-table arrays and find rows having therapy/therapy_type/session fields.
              */
              if (!details.length) {
                Object.keys(doc).forEach(function (key) {
                  if (Array.isArray(doc[key]) && doc[key].length) {
                    var possibleRows = doc[key].some(function (row) {
                      if (!row || typeof row !== "object") return false;

                      return (
                        row.therapy_type ||
                        row.therapy ||
                        row.item ||
                        row.item_code ||
                        row.procedure_template ||
                        row.no_of_sessions ||
                        row.sessions ||
                        row.total_sessions
                      );
                    });

                    if (possibleRows) {
                      details = doc[key];
                    }
                  }
                });
              }

              void 0;
              void 0;

              if (details.length) {
                void 0;

                details.forEach(function (row) {
                  var therapyType = row.therapy_type || "";
                  var serviceUnit = row.service_unit || planCategory || "";

                  var total = Number(row.no_of_sessions || 0);
                  var done = Number(row.sessions_completed || 0);

                  /*
                    If sessions_completed is not maintained in Therapy Plan row,
                    pending will become total.
                    Example: total 6, done 0 = pending 6.
                  */
                  var pending = total - done;

                  if (therapyType && total > 0 && pending > 0) {
                    pendingList.push({
                      therapy_plan: planName,
                      therapy_type: therapyType,
                      service_unit: serviceUnit,
                      start_date: planStartDate,
                      no_of_sessions: total,
                      sessions_completed: done,
                      pending_sessions: pending
                    });
                  }
                });

              } else {
                var topTherapyType =
                  doc.therapy_type ||
                  doc.therapy_type1 ||
                  doc.concern ||
                  doc.item ||
                  "";

                var topServiceUnit =
                  doc.service_unit ||
                  doc.category ||
                  doc.healthcare_service_unit ||
                  "";

                if (topTherapyType) {
                  pendingList.push({
                    therapy_plan: planName,
                    therapy_type: topTherapyType,
                    service_unit: topServiceUnit,
                    start_date: planStartDate,
                    no_of_sessions: 1,
                    sessions_completed: 0,
                    pending_sessions: 1
                  });
                }
              }
            }

            finishLoadingPendingConcerns();
          },

          function (err) {
            loadedCount++;
            void 0;
            finishLoadingPendingConcerns();
          }
        );
      });

      function finishLoadingPendingConcerns() {
        if (loadedCount < rows.length) return;

        var seen = {};

        clientTherapyTypes = pendingList.filter(function (item) {
          var key =
            item.therapy_plan +
            "||" +
            item.therapy_type +
            "||" +
            item.service_unit;

          if (seen[key]) return false;

          seen[key] = true;
          return true;
        });

        void 0;

        if (!clientTherapyTypes.length) {
          modalConcern.placeholder = "No pending concerns found";
          concernSuggestions.innerHTML =
            '<div class="client-option">No pending concerns found</div>';
        } else {
          modalConcern.placeholder = "Click to select pending concern";
        }

        toggleCreateButton();
      }

    }, function (err) {
      void 0;

      modalConcern.placeholder = "Unable to load therapy plans";
      concernSuggestions.innerHTML =
        '<div class="client-option">Unable to load therapy plans. Check console/network.</div>';
      concernSuggestions.classList.remove("hidden");

      toggleCreateButton();
    });
  }

