  function cleanRoomLabel(roomName, branch) {
    if (!roomName) return "";

    var name = String(roomName).trim();
    var b = String(branch || "").trim();

    if (b) {
      name = name.replace(
        new RegExp("\\s*-\\s*" + b.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\s*$", "i"),
        ""
      );
    }

    return name.trim();
  }

  function isRoomForBranch(roomName, branch) {
    if (!roomName || !branch) return false;

    var name = String(roomName).trim().toLowerCase();
    var b = String(branch).trim().toLowerCase();

    return name.endsWith("-" + b) ||
      name.endsWith(" - " + b) ||
      name.includes(b);
  }

  function loadServiceRooms(callback) {
    var branch = branchFilter.value;
    rooms = [];

    if (!branch) {
      callback();
      return;
    }

    xhrPost("frappe.desk.reportview.get", {
      doctype: "Service Room",
      fields: JSON.stringify([
        "`tabService Room`.`name`"
      ]),
      filters: JSON.stringify([]),
      order_by: "`tabService Room`.`idx` asc",
      start: 0,
      page_length: 500,
      view: "List",
      group_by: "",
      with_comment_count: 1
    }, function (data) {
      var rows = data.message && data.message.values ? data.message.values : [];

      rooms = rows
        .map(function (r) {
          return r[0] || "";
        })
        .filter(function (roomName) {
          return isRoomForBranch(roomName, branch);
        })
        .filter(function (roomName, index, arr) {
          return roomName && arr.indexOf(roomName) === index;
        });

      rooms.sort(function (a, b) {
        return cleanRoomLabel(a, branch).localeCompare(
          cleanRoomLabel(b, branch),
          undefined,
          {
            numeric: true,
            sensitivity: "base"
          }
        );
      });

      callback();

    }, function () {
      rooms = [];
      callback();
    });
  }

