  function getStatusClass(status, cb) {
    var v = (cb || "").toLowerCase().trim();

    if (v === "cancel" || v === "cancelled") return "status-cancel";
    if (v === "closed") return "status-closed";
    if (v === "re-scheduled" || v === "rescheduled") return "status-rescheduled";
    if (v === "re-confirm") return "status-reconfirm";
    if (v === "not answering") return "status-notanswering";

    return "status-scheduled";
