  function renderBoard() {
    if (!rooms.length) {
      tableHead.innerHTML = "";
      tableBody.innerHTML =
        '<tr><td class="no-data">No service rooms found for this branch</td></tr>';

      totalCount.textContent = appointments.length;
      availableCount.textContent = "0";
      roomCount.textContent = "0";
      cancelCount.textContent = "0";
      return;
    }

    tableHead.innerHTML =
      "<tr><th>⏱</th>" +
      rooms.map(function(r) {
        var label = cleanRoomLabel(r, branchFilter.value);
        return "<th>" + escapeHtml(label) + "</th>";
      }).join("") +
      "</tr>";

    var html = "";

    timeSlots.forEach(function(slot) {
      html += "<tr><td class='time-cell'>" + escapeHtml(slot) + "</td>";

      rooms.forEach(function(room) {
        var list = appointments.filter(function(a) {
          return a.appointment_time === slot && a.service_room === room;
        });

        if (list.length) {
          html += "<td>";

          list.forEach(function(a) {
            html +=
              "<div class='appt-cell " + getStatusClass(null, a.call_back_status) + "' data-name='" + escapeHtml(a.name) + "'>" +
                "<div class='appt-patient'>" + escapeHtml(a.patient) + "</div>" +
                "<div class='appt-status'>" + escapeHtml(a.call_back_status || a.status || "Scheduled") + "</div>" +
                "<div class='appt-id'>" + escapeHtml(getConcernFromName(a.name)) + "</div>" +
              "</div>";
          });

          html += "</td>";

        } else {
          var showAdd = true;
          var selectedDate = dateFilter.value;
          var today = getTodayDate();

          if (selectedDate < today) {
            showAdd = false;
          } else if (selectedDate === today) {
            var now = new Date();

            var slot24 = convertSlotToERPTime(slot).split(":");
            var slotMinutes =
              parseInt(slot24[0], 10) * 60 +
              parseInt(slot24[1], 10);

            var currentMinutes =
              now.getHours() * 60 +
              now.getMinutes();

            if (slotMinutes <= currentMinutes) {
              showAdd = false;
            }
          }

          if (showAdd) {
            html +=
              "<td class='empty-slot'>" +
                "<button type='button' class='add-appt-btn'" +
                  " data-room='" + escapeHtml(room) + "'" +
                  " data-slot='" + escapeHtml(slot) + "'" +
                  " data-date='" + escapeHtml(dateFilter.value) + "'>" +
                  "+" +
                "</button>" +
              "</td>";
          } else {
            html += "<td class='empty-slot slot-past'>—</td>";
          }
        }
      });

      html += "</tr>";
    });

    tableBody.innerHTML = html;
    updateSummary();
  }

  function updateSummary() {
    var booked = appointments.length;

    var cancelled = appointments.filter(function(a) {
      return ((a.status || "") + " " + (a.call_back_status || ""))
        .toLowerCase()
        .indexOf("cancel") !== -1;
    }).length;

    totalCount.textContent = booked;
    availableCount.textContent = Math.max(timeSlots.length * rooms.length - booked, 0);
    roomCount.textContent = rooms.length;
    cancelCount.textContent = cancelled;
  }

  function handleDetailStatusChange() {
    if (!detailStatusSelect) return;

    if (detailStatusSelect.value === "Re-Scheduled") {
      rescheduleBox.classList.remove("hidden");

      if (selectedAppointmentDoc && selectedAppointmentDoc.appointment_date) {
        var today = getTodayDate();

        rescheduleDate.min = today;

        if (selectedAppointmentDoc.appointment_date >= today) {
          rescheduleDate.value = selectedAppointmentDoc.appointment_date;
        } else {
          rescheduleDate.value = today;
        }
      }

      loadAvailableRescheduleSlots();

    } else {
      rescheduleBox.classList.add("hidden");
    }
  }

  function loadAvailableRescheduleSlots() {
    if (!selectedAppointmentDoc || !rescheduleDate || !rescheduleSlot) return;

    var selectedDate = rescheduleDate.value;

    if (!selectedDate) {
      rescheduleSlot.innerHTML = '<option value="">Select date first</option>';
      return;
    }

    var selectedRoom = selectedAppointmentDoc.service_room;
    var selectedBranch = selectedAppointmentDoc.branch;
    var currentName = selectedAppointmentDoc.name;

    rescheduleSlot.innerHTML = '<option value="">Loading...</option>';

    xhrPost("frappe.desk.reportview.get", {
      doctype: "Patient Appointment",
      fields: JSON.stringify([
        "`tabPatient Appointment`.`name`",
        "`tabPatient Appointment`.`appointment_time`",
        "`tabPatient Appointment`.`service_room`"
      ]),
      filters: JSON.stringify([
        ["Patient Appointment", "appointment_date", "Between", [selectedDate, selectedDate]],
        ["Patient Appointment", "branch", "=", selectedBranch]
      ]),
      order_by: "`tabPatient Appointment`.`appointment_time` asc",
      start: 0,
      page_length: 500,
      view: "List",
      group_by: "",
      with_comment_count: 1
    }, function(data) {
      var rows = data.message && data.message.values ? data.message.values : [];

      var bookedSlots = rows
        .filter(function(r) {
          return r[0] !== currentName && r[2] === selectedRoom;
        })
        .map(function(r) {
          return normalizeTime(r[1]);
        });

      var available = timeSlots.filter(function(slot) {
        return bookedSlots.indexOf(slot) === -1;
      });

      rescheduleSlot.innerHTML =
        '<option value="">Select slot</option>' +
        available.map(function(slot) {
          return '<option value="' + escapeHtml(slot) + '">' +
            escapeHtml(slot) +
          '</option>';
        }).join("");

    }, function() {
      rescheduleSlot.innerHTML =
        '<option value="">Unable to load slots</option>';
    });
  }

  function openAppointmentDetails(name) {
    if (!name) return;

    selectedAppointmentDoc = null;
    detailContent.innerHTML = '<div class="detail-loading">Loading...</div>';

    if (detailStatusSelect) {
      detailStatusSelect.value = "Scheduled";
    }

    rescheduleBox.classList.add("hidden");
    rescheduleSlot.innerHTML = '<option value="">Select slot</option>';

    if (rescheduleDate) {
      rescheduleDate.min = getTodayDate();
    }

    detailModal.classList.remove("hidden");

    xhrGet(
      "/api/method/frappe.desk.form.load.getdoc?doctype=Patient%20Appointment&name=" +
        encodeURIComponent(name) +
        "&_=" + Date.now(),

      function(res) {
        var doc = res.docs && res.docs[0] ? res.docs[0] : null;

        void 0;

        if (!doc) {
          detailContent.innerHTML =
            '<div class="detail-error">Unable to load appointment details.</div>';
          return;
        }

        selectedAppointmentDoc = doc;

        detailContent.innerHTML =
          '<div class="detail-grid">' +
            detailItem("Client", doc.patient_name || doc.patient) +
            detailStatusItem(doc.call_back_status || "Scheduled") +
            detailItem("Mobile", doc.custom_client_mobile_no) +
            detailItem("Gender", doc.patient_sex) +
            detailItem("Branch", doc.branch) +
            detailItem("Service Room", cleanRoomLabel(doc.service_room, doc.branch)) +
            detailItem("Service Unit", doc.service_unit) +
            detailItem("Concern", doc.concern) +
            detailItem("Date & Time", (doc.appointment_date || "-") + " | " + normalizeTime(doc.appointment_time)) +
          '</div>';

        detailStatusSelect = root.querySelector(".detail-status-select");

        if (detailStatusSelect) {
          detailStatusSelect.onchange = handleDetailStatusChange;
        }
      },

      function() {
        detailContent.innerHTML =
          '<div class="detail-error">Unable to load appointment details.</div>';
      }
    );
  }

  function detailStatusItem(value) {
    return '<div class="detail-item detail-status-inline">' +
      '<span>Booking Status</span>' +
      '<select class="detail-status-select">' +
        '<option value="Scheduled"' + (value === "Scheduled" ? " selected" : "") + '>Scheduled</option>' +
        '<option value="Re-Confirm"' + (value === "Re-Confirm" ? " selected" : "") + '>Re-Confirm</option>' +
        '<option value="Re-Scheduled"' + (value === "Re-Scheduled" ? " selected" : "") + '>Re-Scheduled</option>' +
        '<option value="Not Answering"' + (value === "Not Answering" ? " selected" : "") + '>Not Answering</option>' +
        '<option value="Closed"' + (value === "Closed" ? " selected" : "") + '>Closed</option>' +
        '<option value="Cancel"' + (value === "Cancel" ? " selected" : "") + '>Cancel</option>' +
      '</select>' +
    '</div>';
  }

  function detailItem(label, value) {
    return '<div class="detail-item">' +
      '<span>' + escapeHtml(label) + '</span>' +
      '<strong>' + escapeHtml(value || "-") + '</strong>' +
    '</div>';
  }

  function closeAppointmentDetails() {
    detailModal.classList.add("hidden");
    selectedAppointmentDoc = null;
  }

  function addOneHour(slot) {
    var p = convertSlotToERPTime(slot).split(":");
    var h = Number(p[0]) + 1;

    if (h < 10) h = "0" + h;

    return h + ":" + p[1] + ":00";
  }

  function updateAppointmentStatus() {
    if (!selectedAppointmentDoc) {
      frappe.msgprint("Appointment details not loaded.");
      return;
    }

    var newStatus = detailStatusSelect ? detailStatusSelect.value : "Scheduled";

    selectedAppointmentDoc.call_back_status = newStatus;

    if (newStatus === "Re-Scheduled") {
      if (!rescheduleDate.value || !rescheduleSlot.value) {
        frappe.msgprint("Please select new date and available slot.");
        detailSaveBtn.disabled = false;
        detailSaveBtn.textContent = "Update Status";
        return;
      }

      var oldTime = selectedAppointmentDoc.appointment_time;

      selectedAppointmentDoc.call_back_status = "Re-Scheduled";
      selectedAppointmentDoc.appointment_date = rescheduleDate.value;
      selectedAppointmentDoc.appointment_time = convertSlotToERPTime(rescheduleSlot.value);
      selectedAppointmentDoc.custom_duration_time = oldTime;
      selectedAppointmentDoc.__unsaved = 1;
    }

    detailSaveBtn.disabled = true;
    detailSaveBtn.textContent = "Updating...";

    xhrPost("frappe.desk.form.save.savedocs", {
      doc: JSON.stringify(selectedAppointmentDoc),
      action: "Save"
    }, function() {
      detailSaveBtn.disabled = false;
      detailSaveBtn.textContent = "Update Status";

      frappe.show_alert({
        message: "Appointment status updated",
        indicator: "green"
      });

      closeAppointmentDetails();
      loadAppointments();

    }, function(err) {
      detailSaveBtn.disabled = false;
      detailSaveBtn.textContent = "Update Status";

      void 0;
      frappe.msgprint("Failed to update appointment status.");
    });
  }

  function toggleCreateButton() {
    if (!createBtn) return;

    var ready =
      selectedPatient &&
      selectedServiceRoom &&
      selectedCategory &&
      selectedConcern &&
      selectedFinalSlot;

    createBtn.disabled = !ready;

    createBtn.textContent = ready
      ? "Create Appointment"
      : "Fill Required Details";
  }

  function openModal(slotData) {
    selectedPatient = "";
    selectedPatientData = null;
    selectedCategory = "";
    selectedConcern = "";
    selectedServiceRoom = slotData.room || "";
    selectedFinalSlot = slotData.slot || "";

    if (modalClient) modalClient.value = "";
    if (modalClientDetails) modalClientDetails.value = "";
    if (modalCategory) modalCategory.value = "";

    if (modalConcern) {
      modalConcern.value = "";
      modalConcern.placeholder = "Select client first...";
    }

    if (modalServiceRoom) {
      modalServiceRoom.value = selectedServiceRoom;
      modalServiceRoom.readOnly = true;
    }

    if (modalBranchSelect) {
      modalBranchSelect.value = branchFilter.value;
      modalBranchSelect.disabled = true;
    }

    if (modalDateTimeLabel) {
      modalDateTimeLabel.value =
        (slotData.date || dateFilter.value) + " | " + selectedFinalSlot;
    }

    hideAllSuggestions();
    loadModalBranches(branchFilter.value);
    modal.classList.remove("hidden");
    toggleCreateButton();
  }

  function closeModal() {
    modal.classList.add("hidden");
    hideAllSuggestions();
  }

  tableBody.addEventListener("click", function(e) {
    var apptCell = e.target.closest(".appt-cell");
    var addBtn = e.target.closest(".add-appt-btn");

    if (apptCell && apptCell.dataset.name) {
      openAppointmentDetails(apptCell.dataset.name);
      return;
    }

    if (addBtn) {
      openModal({
        room: addBtn.dataset.room || "",
        slot: addBtn.dataset.slot || "",
        date: addBtn.dataset.date || dateFilter.value
      });
    }
  });

  if (rescheduleDate) {
    rescheduleDate.addEventListener("change", loadAvailableRescheduleSlots);
  }

  if (modalClient) {
    bindSearchInput(modalClient, "Patient", clientSuggestions, function(value) {
      validateLink("Patient", value, ["patient_name", "inpatient_record", "sex", "mobile"], function(data) {
        if (!data) return;

        selectedPatient = data.name || value;
        selectedPatientData = data;

        modalClient.value = data.patient_name || data.name || value;

        void 0;
        void 0;

        if (modalClientDetails) {
          modalClientDetails.value = [
            data.patient_name || data.name,
            data.sex || "",
            data.mobile || ""
          ].filter(Boolean).join(" | ");
        }

        loadClientTherapyPlans(selectedPatient);
        toggleCreateButton();
      });
    });
  }

  if (modalCategory) {
    bindSearchInput(modalCategory, "Healthcare Service Unit", categorySuggestions, function(value) {
      validateLink("Healthcare Service Unit", value, [], function(data) {
        selectedCategory = data && data.name ? data.name : value;
        modalCategory.value = selectedCategory;

        selectedConcern = "";

        if (modalConcern) {
          modalConcern.value = "";
          modalConcern.placeholder = "Click to select pending concern";
        }

        toggleCreateButton();
      });
    });
  }

  if (modalConcern) {
    modalConcern.addEventListener("focus", showClientTherapyTypeSuggestions);
    modalConcern.addEventListener("click", showClientTherapyTypeSuggestions);

    modalConcern.addEventListener("input", function() {
      showClientTherapyTypeSuggestions();
    });

    modalConcern.addEventListener("blur", function() {
      setTimeout(function() {
        if (!concernSuggestions.matches(":hover")) {
          concernSuggestions.classList.add("hidden");
        }
      }, 260);
    });
  }

  if (detailModalClose) {
    detailModalClose.addEventListener("click", closeAppointmentDetails);
  }

  if (detailCancelBtn) {
    detailCancelBtn.addEventListener("click", closeAppointmentDetails);
  }

  if (detailSaveBtn) {
    detailSaveBtn.addEventListener("click", updateAppointmentStatus);
  }

  if (detailModal) {
    detailModal.addEventListener("click", function(e) {
      if (e.target === detailModal) {
        closeAppointmentDetails();
      }
    });
  }

  if (modalClose) {
    modalClose.addEventListener("click", closeModal);
  }

  if (cancelBtn) {
    cancelBtn.addEventListener("click", closeModal);
  }

  if (modal) {
    modal.addEventListener("click", function(e) {
      if (e.target === modal) {
        closeModal();
      }
    });
  }

  function createAppointment() {
    if (isCreating) return;

    if (!selectedPatient || !selectedServiceRoom || !selectedCategory || !selectedConcern || !selectedFinalSlot) {
      frappe.msgprint("Please fill all required fields.");
      return;
    }

    var snap = {
      slot: selectedFinalSlot,
      room: selectedServiceRoom,
      branch: branchFilter.value,
      date: dateFilter.value,
      patient: selectedPatient,
      patName: selectedPatientData && selectedPatientData.patient_name
        ? selectedPatientData.patient_name
        : (modalClient ? modalClient.value : selectedPatient),
      category: selectedCategory,
      concern: selectedConcern,
      iRecord: selectedPatientData ? (selectedPatientData.inpatient_record || null) : null,
      sex: selectedPatientData ? (selectedPatientData.sex || "") : "",
      mobile: selectedPatientData ? (selectedPatientData.mobile || "") : ""
    };

    isCreating = true;
    createBtn.disabled = true;
    createBtn.textContent = "Creating...";

    var doc = {
      docstatus: 0,
      doctype: "Patient Appointment",
      name: "new-patient-appointment-" + Date.now(),
      __islocal: 1,
      __unsaved: 1,

      naming_series: "HLC-APP-.YYYY.-",
      status: "",
      call_back_status: "Scheduled",

      appointment_for: "Practitioner",
      company: "Life Slimming And Cosmetic Pvt Ltd",
      add_video_conferencing: 0,
      invoiced: 0,
      appointment_based_on_check_in: 0,
      reminded: 0,

      appointment_type: "Session",
      department: "",

      service_unit: snap.category,
      patient: snap.patient,
      patient_name: snap.patName,
      inpatient_record: snap.iRecord,
      patient_sex: snap.sex,
      custom_client_mobile_no: snap.mobile,

      duration: null,
      service_room: snap.room,
      concern: snap.concern,

      appointment_date: snap.date,
      appointment_time: convertSlotToERPTime(snap.slot),
      branch: snap.branch
    };

    xhrPost("frappe.desk.form.save.savedocs", {
      doc: JSON.stringify(doc),
      action: "Save"
    }, function(data) {
      unlockCreateBtn();

      var savedDoc = null;

      if (data.docs && data.docs[0]) {
        savedDoc = data.docs[0];
      } else if (data.message && data.message.docs && data.message.docs[0]) {
        savedDoc = data.message.docs[0];
      }

      if (!savedDoc || !savedDoc.name) {
        frappe.msgprint("Appointment was not saved. Please try again.");
        return;
      }

      closeModal();

      appointments.push({
        name: savedDoc.name,
        status: savedDoc.status || "",
        service_room: savedDoc.service_room || snap.room,
        branch: savedDoc.branch || snap.branch,
        appointment_date: savedDoc.appointment_date || snap.date,
        patient: savedDoc.patient_name || savedDoc.patient || snap.patName,
        appointment_time: snap.slot,
        call_back_status: savedDoc.call_back_status || "Scheduled"
      });

      renderBoard();

      frappe.show_alert({
        message: "Appointment created successfully",
        indicator: "green"
      });

      setTimeout(loadAppointments, 1500);

    }, function(err) {
      unlockCreateBtn();
      void 0;
      frappe.msgprint("Failed to create appointment. Check console for details.");
    });
  }

  if (createBtn) {
    createBtn.addEventListener("click", createAppointment);
  }

  branchFilter.addEventListener("change", loadAppointments);
  dateFilter.addEventListener("change", loadAppointments);
  refreshBtn.addEventListener("click", loadAppointments);

  stopAwesomeBarTyping();

  dateFilter.value = getTodayDate();
  loadBranches();

  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initClientAppointmentScheduler);
  } else {
    initClientAppointmentScheduler();
  }
})();
